import java.util.HashSet;
import java.util.Iterator;
import java.util.Set;

public class SetExample {

    public static void main(String[] args) {
        // Creating a HashSet
        Set<String> fruits = new HashSet<>();

        // Adding elements to the Set
        fruits.add("Apple");
        fruits.add("Banana");
        fruits.add("Orange");
        fruits.add("Grapes");
        fruits.add("Apple");  // Duplicate element, will not be added

        // Displaying the Set
        System.out.println("Set of fruits: " + fruits);

        // Checking if an element exists in the Set
        boolean hasBanana = fruits.contains("Banana");
        System.out.println("Does the set contain 'Banana'? " + hasBanana);

        // Removing an element from the Set
        fruits.remove("Grapes");
        System.out.println("Set of fruits after removing 'Grapes': " + fruits);

        // Iterating over the Set
        System.out.println("Iterating over the set:");
        for (String fruit : fruits) {
            System.out.println(fruit);
        }

        // Using an Iterator to iterate over the Set
        System.out.println("Using an Iterator to iterate over the set:");
        Iterator<String> iterator = fruits.iterator();
        while (iterator.hasNext()) {
            String fruit = iterator.next();
            System.out.println(fruit);
        }

        // Checking the size of the Set
        int setSize = fruits.size();
        System.out.println("Size of the set: " + setSize);

        // Clearing the Set
        fruits.clear();
        System.out.println("Set of fruits after clearing: " + fruits);
    }
}
